#include "crt.h"
// Base64 encode a generated byte buffer, decode it back with a reverse lookup table, verify, and checksum the text.
#define N 1201
static const char tab[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
static unsigned char raw[N], back[N];
static char text[(N + 2) / 3 * 4 + 1];
static signed char rev[256];
static int encode(const unsigned char *in, int n, char *out) {
    int o = 0;
    for (int i = 0; i < n; i += 3) {
        unsigned v = (unsigned)in[i] << 16 | (i + 1 < n ? (unsigned)in[i + 1] << 8 : 0) | (i + 2 < n ? in[i + 2] : 0);
        out[o++] = tab[v >> 18 & 63];
        out[o++] = tab[v >> 12 & 63];
        out[o++] = i + 1 < n ? tab[v >> 6 & 63] : '=';
        out[o++] = i + 2 < n ? tab[v & 63] : '=';
    }
    out[o] = 0;
    return o;
}
static int decode(const char *in, int n, unsigned char *out) {
    int o = 0;
    for (int i = 0; i + 3 < n; i += 4) {
        unsigned v = 0;
        int pad = 0;
        for (int k = 0; k < 4; ++k) {
            char c = in[i + k];
            if (c == '=') { ++pad; v <<= 6; } else v = v << 6 | (unsigned)rev[(unsigned char)c];
        }
        out[o++] = (unsigned char)(v >> 16);
        if (pad < 2) out[o++] = (unsigned char)(v >> 8);
        if (pad < 1) out[o++] = (unsigned char)v;
    }
    return o;
}
int cmain(void) {
    for (int i = 0; i < 256; ++i) rev[i] = -1;
    for (int i = 0; i < 64; ++i) rev[(unsigned char)tab[i]] = (signed char)i;
    unsigned s = 77;
    for (int i = 0; i < N; ++i) { s = s * 22695477u + 1; raw[i] = (unsigned char)(s >> 16); }
    int t = encode(raw, N, text);
    int d = decode(text, t, back);
    u64 same = (u64)(d == N), h = 5381;
    for (int i = 0; i < N; ++i) same &= (u64)(raw[i] == back[i]);
    for (int i = 0; i < t; ++i) h = h * 33 + (unsigned char)text[i];
    put_u64((u64)t); put_u64(same); put_u64(h);
    return 0;
}
